{"implementation":"def solve(case):
    edges = case['edges']
    communities = dict(case['communities'])
    gamma = case['resolution']
    adj = {}
    deg = {}
    for u, v, w in edges:
        adj.setdefault(u, {})[v] = adj.get(u, {}).get(v, 0) + w
        adj.setdefault(v, {})[u] = adj.get(v, {}).get(u, 0) + w
        deg[u] = deg.get(u, 0) + w
        deg[v] = deg.get(v, 0) + w
    total_weight = sum(w for _,_,w in edges)
    m2 = 2 * total_weight
    sum_tot = {}
    for node, comm in communities.items():
        sum_tot[comm] = sum_tot.get(comm, 0) + deg.get(node, 0)
    nodes_sorted = sorted(communities.keys())
    ledger = []
    changed = True
    while changed:
        changed = False
        for node in nodes_sorted:
            cur_comm = communities[node]
            w_per_comm = {}
            for neighbor, w in adj.get(node, {}).items():
                ncomm = communities[neighbor]
                w_per_comm[ncomm] = w_per_comm.get(ncomm, 0) + w
            best_comm = cur_comm
            cur_score = w_per_comm.get(cur_comm, 0) - gamma * deg.get(node, 0) * sum_tot[cur_comm] / m2
            best_score = cur_score
            for comm, w_comm in w_per_comm.items():
                if comm == cur_comm:
                    continue
                score = w_comm - gamma * deg.get(node, 0) * sum_tot[comm] / m2
                if score > best_score or (score == best_score and comm < best_comm):
                    best_score = score
                    best_comm = comm
            if best_comm != cur_comm:
                old_comm = cur_comm
                new_comm = best_comm
                sum_tot[old_comm] -= deg.get(node, 0)
                sum_tot[new_comm] += deg.get(node, 0)
                communities[node] = new_comm
                ledger.append([node, old_comm, new_comm])
                changed = True
    return {"labels": communities, "ledger": ledger}"}
